#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long S;
    if (!(cin >> n >> S)) return 0;
    vector<int> a(n);
    for (int &x : a) cin >> x;

    long long answer = 0;
    long long curSum = 0;
    int left = 0; // 0‑based index

    for (int right = 0; right < n; ++right) {
        curSum += a[right];
        while (curSum > S && left <= right) {
            curSum -= a[left];
            ++left;
        }
        // now sum of [left, right] <= S
        answer += (right - left + 1);
    }

    cout << answer << '\n';
    return 0;
}

