// Long long type for large distances
using ll = long long;

// Edge representation
struct Edge {
    int to;     // destination town
    int weight; // cost of the road
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    vector<vector<Edge>> graph(n + 1); // 1-indexed

    for (int i = 0; i < m; ++i) {
        int u, v, w;
        cin >> u >> v >> w;
        graph[u].push_back({v, w});
        graph[v].push_back({u, w}); // undirected road
    }

    const ll INF = 4e18;          // sufficiently large
    vector<ll> dist(n + 1, INF);  // shortest known distance from town 1
    priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<>> pq;

    dist[1] = 0;
    pq.push({0, 1});

    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (d != dist[u]) continue;          // outdated entry

        for (const auto& e : graph[u]) {
            int v = e.to;
            ll nd = d + e.weight;
            if (nd < dist[v]) {
                dist[v] = nd;
                pq.push({nd, v});
            }
        }
    }

    if (dist[n] == INF) cout << -1 << '\n';
    else cout << dist[n] << '\n';

    return 0;
}

