import sys, heapq

def solve() -> None:
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it)); m = int(next(it))
    g = [[] for _ in range(n + 1)]
    for _ in range(m):
        u = int(next(it)); v = int(next(it)); w = int(next(it))
        g[u].append((v, w))
        g[v].append((u, w))
    INF = 10**18
    dist = [INF] * (n + 1)
    dist[1] = 0
    h = [(0, 1)]
    while h:
        d, u = heapq.heappop(h)
        if d != dist[u]:
            continue
        if u == n:
            break
        for v, w in g[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(h, (nd, v))
    print(-1 if dist[n] == INF else dist[n])

if __name__ == "__main__":
    solve()

