// Compute divisor counts for all numbers up to maxVal
vector<int> computeDivisorCounts(int maxVal) {
    vector<int> divCnt(maxVal + 1, 0);
    for (int i = 1; i <= maxVal; ++i) {
        for (int j = i; j <= maxVal; j += i) {
            ++divCnt[j];
        }
    }
    return divCnt;
}

