#include <bits/stdc++.h>
using namespace std;

struct Item {
    long long w, v;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long W;
    if (!(cin >> n >> W)) return 0;
    vector<Item> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i].w >> a[i].v;
    sort(a.begin(), a.end(), [](const Item& x, const Item& y) {
        return (__int128)x.v * y.w > (__int128)y.v * x.w;
    });
    long long remaining = W;
    long double total = 0.0L;
    for (const auto& it : a) {
        if (!remaining) break;
        long long take = min(remaining, it.w);
        total += (long double)take * it.v / it.w;
        remaining -= take;
    }
    cout.setf(ios::fixed); cout << setprecision(10) << (double)total << '\n';
    return 0;
}

