import sys

def read_input() -> list:
    """Read all lines from stdin and return a list of (name, score) tuples."""
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return []
    n = int(data[0])
    entries = []
    for line in data[1:n+1]:
        name, score_str = line.split()
        entries.append((name, int(score_str)))
    return entries

def sort_leaderboard(entries: list) -> list:
    """Return entries sorted by descending score, then ascending name."""
    return sorted(entries, key=lambda item: (-item[1], item[0]))

def solve() -> None:
    entries = read_input()
    sorted_entries = sort_leaderboard(entries)
    out_lines = [f"{name} {score}" for name, score in sorted_entries]
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()

