import sys

def build_prefix_function(pattern: str) -> list[int]:
    """Construct the longest proper prefix which is also suffix array."""
    m = len(pattern)
    pi = [0] * m
    j = 0
    for i in range(1, m):
        while j > 0 and pattern[i] != pattern[j]:
            j = pi[j - 1]
        if pattern[i] == pattern[j]:
            j += 1
            pi[i] = j
    return pi

def count_occurrences(text: str, pattern: str) -> int:
    """Return the number of (possibly overlapping) occurrences of pattern in text."""
    n, m = len(text), len(pattern)
    if m > n:
        return 0
    pi = build_prefix_function(pattern)
    count = 0
    j = 0  # current length of matched prefix in pattern
    for i in range(n):
        while j > 0 and text[i] != pattern[j]:
            j = pi[j - 1]
        if text[i] == pattern[j]:
            j += 1
            if j == m:
                count += 1
                j = pi[j - 1]  # allow overlapping
    return count

def main() -> None:
