// A struct representing a parcel to be delivered.
struct Parcel {
    int weight;
    long long value;
};

// Reads the inputs from standard input.
void read_input(int& total_parcels, int& max_van_capacity, std::vector<Parcel>& parcel_list) {
    if (!(std::cin >> total_parcels >> max_van_capacity)) {
        return;
    }
    parcel_list.resize(total_parcels);
    for (int i = 0; i < total_parcels; ++i) {
        std::cin >> parcel_list[i].weight >> parcel_list[i].value;
    }
}

// Computes the maximum possible earnings using 0-1 Knapsack Dynamic Programming.
long long calculate_maximum_earnings(int max_van_capacity, const std::vector<Parcel>& parcel_list) {
    // max_earnings_by_weight[w] stores the maximum value we can get with a total weight of at most w.
    std::vector<long long> max_earnings_by_weight(max_van_capacity + 1, 0LL);

    for (const auto& current_parcel : parcel_list) {
        // We iterate backwards to ensure we only use each parcel at most once.
        for (int current_capacity = max_van_capacity; current_capacity >= current_parcel.weight; --current_capacity) {
            long long earnings_if_we_take_parcel = max_earnings_by_weight[current_capacity - current_parcel.weight] + current_parcel.value;
            long long earnings_if_we_skip_parcel = max_earnings_by_weight[current_capacity];

            max_earnings_by_weight[current_capacity] = std::max(earnings_if_we_skip_parcel, earnings_if_we_take_parcel);
        }
    }

    return max_earnings_by_weight[max_van_capacity];
}

