    int first_occurrence_index;
};

// This helper function finds the maximum value and its first 1-based index
// in a given list of temperature readings.
PeakReadingResult find_peak_reading(const std::vector<long long>& temperature_readings) {
    // We assume the list is not empty because the problem statement guarantees 1 <= n.
    long long max_value = temperature_readings[0];
    int best_index = 1; // 1-based index of the first reading

    for (size_t current_index = 0; current_index < temperature_readings.size(); ++current_index) {
        long long current_value = temperature_readings[current_index];
        // If we find a value strictly greater than our current maximum,
        // we update the maximum and its 1-based index.
        if (current_value > max_value) {
            max_value = current_value;
            best_index = static_cast<int>(current_index) + 1;
        }
    }

    PeakReadingResult result;
    result.maximum_value = max_value;
    result.first_occurrence_index = best_index;
    return result;
}

