/*  Returns the 1‑based position of the first element in the sorted
    vector `sortedValues` that is >= `target`.  If no such element exists,
    returns `sortedValues.size() + 1`.                                            */
static int firstPositionAtLeast(const vector<int>& sortedValues, int target) {
    auto it = lower_bound(sortedValues.begin(), sortedValues.end(), target);
    if (it == sortedValues.end())
        return static_cast<int>(sortedValues.size()) + 1;   // no element large enough
    return static_cast<int>(it - sortedValues.begin()) + 1; // convert to 1‑based index
}

