// Compute the Levenshtein distance (minimum number of single-letter edits)
// to transform string a into string b.
int editDistance(const string& a, const string& b) {
    int n = a.size();
    int m = b.size();

    // Use a 2D DP array: dp[i][j] = distance between a[0..i) and b[0..j)
    vector<vector<int>> dp(n + 1, vector<int>(m + 1));

    // Base cases: transforming empty string to prefixes
    for (int i = 0; i <= n; ++i) dp[i][0] = i;   // delete i characters
    for (int j = 0; j <= m; ++j) dp[0][j] = j;   // insert j characters

    // Fill DP table
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= m; ++j) {
            if (a[i - 1] == b[j - 1]) {
                // No edit needed for the last characters
                dp[i][j] = dp[i - 1][j - 1];
            } else {
                // Minimum of replace, insert, delete
                int replaceCost = dp[i - 1][j - 1];
                int insertCost  = dp[i][j - 1];
                int deleteCost  = dp[i - 1][j];
                dp[i][j] = 1 + min({replaceCost, insertCost, deleteCost});
            }
        }
    }
    return dp[n][m];
}

